shell_commands:
node --input-type=module -e "
import reLint from '@re-cinq/eslint-plugin-re-lint';
for (const name of ['no-catch-as-control-flow', 'max-expects', 'no-vague-names', 'no-negative-names', 'require-spec-link', 'require-status-matches-coverage', 'callee-below-caller', 'max-comment-lines']) {
  const r = reLint.rules[name];
  console.log('=== ' + name + ' ===');
  console.log(r?.meta?.docs?.description ?? '');
  console.log(String(r?.create).slice(0, 600));
}
"

node --input-type=module -e "
import {readFileSync} from 'node:fs';
import {createRequire} from 'node:module';
const req = createRequire(import.meta.url);
const base = req.resolve('@re-cinq/eslint-plugin-re-lint').replace(/index\.js$/, '');
for (const f of ['rules/no-vague-names.js', 'rules/no-negative-names.js', 'rules/no-catch-as-control-flow.js', 'rules/no-hybrid-class.js']) {
  console.log('=== ' + f + ' ===');
  console.log(readFileSync(base + f, 'utf8'));
}
"

