node --input-type=module -e "
import {readFileSync} from 'node:fs';
const s = readFileSync('./node_modules/@re-cinq/eslint-plugin-re-lint/dist/index.mjs', 'utf8');
for (const pat of [/DEFAULT_VAGUE_NAMES[\s\S]{0,400}/, /NEGATIVE_PREFIX[\s\S]{0,500}/, /swallowsError[\s\S]{0,600}/, /noHybridClass[\s\S]{0,600}/]) {
